using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Reflection;
namespace Downfield {
public static class PresentationUpdateTests {
 static int checks,failures;static void Check(bool ok,string label){checks++;if(!ok){failures++;Console.WriteLine("FAIL Presentation update: "+label);}}
 static void Call(object instance,string name,params object[] args){instance.GetType().GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(instance,args);}
 static int LogoHash(Bitmap image){int hash=17;for(int x=0;x<image.Width;x++)for(int y=0;y<image.Height;y++)hash=unchecked(hash*31+image.GetPixel(x,y).ToArgb());return hash;}
 public static int Run(){checks=failures=0;string old=Profile.StorageOverride,folder=Path.Combine(Path.GetTempPath(),"Downfield-presentation-"+Guid.NewGuid().ToString("N"));Profile.StorageOverride=Path.Combine(folder,"club.txt");try{
  Franchise f=Franchise.Create(new Profile(),new Roster());HashSet<int> logos=new HashSet<int>();foreach(LeagueTeam team in f.Teams)logos.Add(LogoHash(TeamLogos.Get(team)));Check(logos.Count==12,"all twelve teams have distinct original pixel logos");int original=LogoHash(TeamLogos.Get(f.Club));f.Edit(1,7,1);Check(LogoHash(TeamLogos.Get(f.Club))!=original,"mascot and color edits change the team logo");
  Simulation s=new Simulation(92);s.Practice=true;s.NewGame();Check(!s.DirectReceiver(0,1,0),"receiver commands are unavailable before snap");s.Snap();Player r=s.Receiver(0);float before=r.X;Check(s.DirectReceiver(0,1,0),"QB commands an eligible receiver");for(int n=0;n<75;n++)s.Update(1f/60,0,0);Check(r.X>before+4&&r.CommandUntil>0&&s.State==Phase.Live,"command produces grounded receiver movement without a pass");s.BeginPass(0);s.Charge=.35f;s.ReleasePass();Check(s.State==Phase.Flight&&Math.Abs(s.FlightTargetX-r.CommandX)<3,"pass forecast follows the commanded route");s=new Simulation(92);s.Practice=true;s.NewGame();s.Snap();s.Controlled.Z=s.Spot+1;Check(!s.DirectReceiver(1,-1,0),"playmaker ends after crossing scrimmage");s.Controlled.Z=s.Spot-1;s.Receiver(1).Active=false;Check(!s.DirectReceiver(1,-1,0),"cannot command an absent or injured receiver");s.Receiver(1).Active=true;s.DirectReceiver(1,0,-1);Check(s.Receiver(1).CommandZ>=s.Spot+1,"comeback stays in the playable passing field");s.State=Phase.Dead;s.Next();Check(s.Receiver(1).CommandUntil==0,"next play clears all scramble commands");
  int rain=0,snow=0,domeWet=0;bool predictable=true;foreach(string city in Franchise.Cities)for(int season=1;season<=4;season++)for(int week=0;week<14;week++){s=new Simulation(123);s.WeatherSelection=0;s.VenueCity=city;s.VenueSeason=season;s.VenueWeek=week;s.VenueFixture=week*6+1;s.NewGame();MatchWeather weather=s.Weather;int temp=s.Temperature;rain+=weather==MatchWeather.Rain?1:0;snow+=weather==MatchWeather.Snow?1:0;if(s.Indoor&&weather!=MatchWeather.Clear)domeWet++;s.NewGame();predictable&=s.Weather==weather&&s.Temperature==temp;}Check(rain>100&&snow>15&&domeWet==0&&predictable,"seasonal city forecasts include rain and cold-city snow while roofs stay dry");
  s=new Simulation(32);s.WeatherSelection=3;s.VenueCity="MIAMI";s.NewGame();Check(s.Weather==MatchWeather.Snow&&!s.Indoor&&s.Temperature<=32&&s.SurfaceGrip<1,"exhibition snow override works and changes surface grip");Player dry=new Player(0,0,0,"WR",80,8),wet=new Player(0,0,0,"WR",80,8);wet.Grip=s.SurfaceGrip;for(int i=0;i<15;i++){Simulation.GroundStep(dry,0,1,8,1f/60);Simulation.GroundStep(wet,0,1,8,1f/60);}Check(wet.Z<dry.Z-.03f,"snow affects footing rather than just painting the screen");f=Franchise.Create(new Profile(),new Roster());f.UserTeam=7;Fixture fixture=f.UserGame;s=new Simulation(22);f.Apply(s,fixture.Opponent(f.UserTeam));Check(s.VenueCity==f.Teams[fixture.Home].City&&s.VenueTeam==fixture.Home&&s.VenueAwayTeam==fixture.Away,"away franchise games use the actual home venue");s.NewGame();Check(s.MatchIntroTime>0,"new game has a broadcast introduction");s.Snap();Check(s.MatchIntroTime==0,"snap dismisses presentation immediately");
  HashSet<int> variations=new HashSet<int>();bool bounded=true;s=new Simulation(19);for(int hit=0;hit<18;hit++){Player victim=s.Players[1];Call(s,"KnockDown",victim,4f,10f,22f);variations.Add(victim.HitStyle);for(int frame=0;frame<80;frame++)Call(s,"UpdateKnockbacks",1f/60);bounded&=victim.KnockTime==0&&Math.Abs(victim.KnockVX)<.001f;}Check(variations.Count==6&&bounded,"six hit styles settle into safe physical knockdowns");s=new Simulation(1);s.Difficulty=4;s.NewGame();s.Snap();s.Controlled.VX=s.Controlled.VZ=0;s.Players[11].VX=s.Players[11].VZ=0;Call(s,"RegisterHit",s.Players[11]);Check(s.ImpactPower==2&&s.SpectacularHits==1&&s.Controlled.KnockTime>0,"even low-speed SPRXTRM tackles use the huge hit animation");
  f=Franchise.Create(new Profile(),new Roster());f.Credits=44;Check(!f.RelocateCustom("MOSS POINT")&&f.Credits==44,"custom relocation requires full $45M");f.Credits=100;int id=f.Starter(f.UserTeam,0).Id;Check(f.RelocateCustom("  Moss   Point ")&&f.Club.City=="MOSS POINT"&&f.Credits==55&&f.Starter(f.UserTeam,0).Id==id,"custom city normalizes input and charges base15 plus extra30 without changing roster");Check(!f.RelocateCustom("NEW ORLEANS")&&!f.RelocateCustom("X")&&!f.RelocateCustom("BAD<CITY>"),"occupied and invalid custom cities cannot charge money");Franchise saved=Franchise.Load(new Profile(),new Roster());Check(saved.Club.City=="MOSS POINT"&&saved.Credits==55,"custom city and cost persist in the existing franchise format");
  while(!f.Complete){if(f.UserGame==null)f.Advance();else f.FinishGame(f.UserGame.Id,35,7);}TeamSeason history=f.History.Find(h=>h.Team==f.UserTeam);int logo=LogoHash(TeamLogos.Get(new LeagueTeam{Id=history.Team,Mascot=history.LogoMascot,Primary=history.LogoPrimary,Secondary=history.LogoSecondary}));f.Edit(3,5,0);Check(logo!=LogoHash(TeamLogos.Get(f.Club))&&history.Name.Contains("MOSS POINT"),"completed seasons retain the historical team name and logo");
  new GamePreferences{Difficulty=4}.Save();Check(GamePreferences.Load().Difficulty==4,"SPRXTRM is persisted as the fifth mode");
 }finally{Profile.StorageOverride=old;if(Directory.Exists(folder))Directory.Delete(folder,true);}Console.WriteLine("Presentation update: "+checks+" checks, "+failures+" failures");return failures;}
}
}
